/* Phase 02 review model: memory-only interactions; no backend or real uploads. */
const params = new URLSearchParams(location.search);
let lang = params.get('lang') === 'en' ? 'en' : 'ar';
let theme = params.get('theme') || (matchMedia('(prefers-color-scheme:dark)').matches ? 'dark' : 'light');
let reduced = params.get('motion') === 'reduced';
let filter = 'all', search = '', tab = 'content', current = 'P001', context = '';
let sampleReady = false, saved = false, mockPublished = false;
let formValues = {}, galleryIndex = 0;
const projects = window.DESIGN_PROJECTS;
const t = (ar,en) => lang === 'ar' ? ar : en;
const esc = value => String(value ?? '').replace(/[&<>"']/g,c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {
  arrow:'<path d="M4 10h12m-5-5 5 5-5 5"/>', plus:'<path d="M10 3v14M3 10h14"/>', menu:'<path d="M3 5h14M3 10h14M3 15h14"/>',
  sun:'<circle cx="10" cy="10" r="3"/><path d="M10 1v2m0 14v2M1 10h2m14 0h2M4 4l1.5 1.5m9 9L16 16M4 16l1.5-1.5m9-9L16 4"/>',
  moon:'<path d="M16 12A7 7 0 0 1 8 3a7 7 0 1 0 8 9Z"/>', close:'<path d="m4 4 12 12M16 4 4 16"/>',
  grid:'<rect x="3" y="3" width="5" height="5" rx="1"/><rect x="12" y="3" width="5" height="5" rx="1"/><rect x="3" y="12" width="5" height="5" rx="1"/><rect x="12" y="12" width="5" height="5" rx="1"/>',
  image:'<rect x="2" y="3" width="16" height="14" rx="2"/><circle cx="7" cy="7" r="1"/><path d="m3 15 4-4 3 3 3-5 4 6"/>',
  user:'<circle cx="10" cy="6" r="3"/><path d="M4 18v-2a6 6 0 0 1 12 0v2"/>', settings:'<path d="M3 5h14M3 10h14M3 15h14"/><circle cx="7" cy="5" r="2"/><circle cx="13" cy="10" r="2"/><circle cx="7" cy="15" r="2"/>',
  check:'<path d="m3 10 4 4 10-10"/>', alert:'<path d="m10 2 8 15H2Z"/><path d="M10 7v4m0 3v.5"/>', upload:'<path d="M10 13V2m-4 4 4-4 4 4M3 12v5h14v-5"/>',
  play:'<path d="m7 4 9 6-9 6Z"/>', mail:'<rect x="2" y="4" width="16" height="12" rx="2"/><path d="m2 5 8 6 8-6"/>', eye:'<path d="M1 10s3-6 9-6 9 6 9 6-3 6-9 6-9-6-9-6Z"/><circle cx="10" cy="10" r="2"/>'
};
function icon(name, extra='') { return `<svg class="icon ${extra}" viewBox="0 0 20 20" aria-hidden="true">${icons[name] || icons.grid}</svg>`; }
const name = p => lang === 'ar' ? p.name : p.en;
const groupName = g => ({all:t('كل الأعمال','All work'),systems:t('أنظمة إدارة','Management systems'),sites:t('مواقع وخدمات','Websites & services'),store:t('تجارة إلكترونية','E-commerce'),games:t('ألعاب وتفاعل','Games & experiences')})[g];
function thumb(p, label=true) { return `<span class="thumb" style="--x:${p.x};--y:${p.y}" role="img" aria-label="${esc(t('لقطة مرجعية: ','Reference screenshot: ')+name(p))}"></span>${label ? `<div class="visual-label">${t('لقطة من مرجع الأعمال — تستبدل بالأصل','From the supplied overview — original needed')}</div>` : ''}`; }
function brand() { return '<a class="brand" href="#home" aria-label="YOGEN"><img src="../../../../planning-assets/yogen-logo-horizontal.png" alt="YOGEN — Ideas for a brighter tomorrow" width="1280" height="249"></a>'; }
function btn(text,action,primary=false,ic='') { return `<button type="button" class="btn ${primary?'primary':''}" data-action="${action}">${ic?icon(ic):''}${text}</button>`; }
function link(text,to,primary=false) { return `<a class="btn ${primary?'primary':''}" href="#${to}">${text}${icon('arrow','arrow')}</a>`; }
function toast(text) { const live=document.querySelector('#live'); live.textContent=text; clearTimeout(window.toastTimer); window.toastTimer=setTimeout(()=>live.textContent='',5000); }
function route() { return location.hash.slice(1) || 'home'; }
function footer() { return `<footer><div class="wrap spread"><span class="latin">YOGEN · Ideas for a brighter tomorrow</span><span>${t('تطوير تطبيقات حسب احتياجك','Custom software for your needs')}</span></div></footer>`; }
function sectionHead(title,sub,action='') { return `<div class="section-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`; }
function pageHead(kicker,title,sub) { return `<div class="page-head"><div class="eyebrow">${kicker}</div><h1>${title}</h1>${sub?`<p class="muted">${sub}</p>`:''}</div>`; }
function card(p) { return `<a class="project-card" href="#project/${p.id}" data-project="${p.id}">${thumb(p,false)}<div class="project-copy"><div class="meta"><span>${groupName(p.group)}</span>${icon('arrow','arrow')}</div><h3>${esc(name(p))}</h3><p class="small muted">${t('مرجع تصميم؛ التفاصيل يضيفها الفريق لاحقًا.','Design reference; the team will add the project details.')}</p></div></a>`; }
function cta() { return `<div class="cta-band"><div class="stack-sm"><h2>${t('فكرتك، الخطوة الجاية.','Your idea. Our next chapter.')}</h2><p class="muted">${t('احكيلنا عن احتياجك، ونبدأ بتحديد الحل المناسب.','Tell us what you need. Let’s define the right solution.')}</p></div>${link(t('ابدأ مشروعك','Start your project'),'contact',true)}</div>`; }
function home() {
  return `<main id="main" tabindex="-1"><div class="wrap">
    <section class="hero"><div class="hero-copy">
      <div class="eyebrow">${t('YOGEN / تطوير برمجيات حسب الطلب','YOGEN / CUSTOM SOFTWARE DEVELOPMENT')}</div>
      <h1>${t('أفكارك تستحق<br><span class="accent">تطبيقًا يليق بها.</span>','Your ideas deserve<br><span class="accent">exceptional software.</span>')}</h1>
      <p class="muted">${t('نطوّر تطبيقات برمجية حسب احتياجك. استكشف أعمالنا، وشوف نقطة البداية لمشروعك القادم.','We develop software around your needs. Explore our work and find the starting point for your next project.')}</p>
      <div class="row">${link(t('ابدأ مشروعك','Start your project'),'contact',true)}${link(t('استكشف كل الأعمال','Explore all work'),'work')}</div>
      <div class="hero-foot"><span class="dot"></span><span>${t('من فكرة واضحة إلى تجربة عملية','From a clear idea to a useful experience')}</span></div>
      <button class="scroll-cue btn ghost" data-action="scroll-work"><i aria-hidden="true"></i>${t('شوف الأفكار اللي اتحولت لعمل','Explore ideas brought to life')}</button>
    </div><div class="hero-art">
      <div class="sculpture-stage">
        <div class="scene-top"><span>YOGEN / IDEAS IN MOTION</span><div class="scene-mark" aria-hidden="true"><i></i><i></i><i></i></div></div>
        <canvas aria-hidden="true"></canvas>
        <div class="scene-fallback" aria-hidden="true"><img src="../../../../planning-assets/yogen-logo-square.png" alt="" width="1254" height="1254"></div>
        <div class="scene-footer"><span>${t('أفكار لمستقبل أكثر إشراقًا.','Ideas for a brighter tomorrow.')}</span><button class="scene-pause" data-action="pause-scene" aria-pressed="false">${t('إيقاف الحركة','Pause motion')}</button></div>
      </div>
      <a class="hero-mini-work" href="#project/P002" data-project="P002" aria-label="${esc(t('استكشف مشروع عيادة الطبيب','Explore the medical clinic project'))}">${thumb(projects[1],false)}<p>${t('من أفكارنا إلى أعمالنا','From our ideas to our work')}${icon('arrow','arrow')}</p></a>
      <a class="hero-badge" href="#work"><b>15</b><span>${t('مشروعًا في المعاينة','projects in this preview')}</span></a>
    </div></section>
    <div class="intro-line"><strong>${t('برمجيات تبدأ بفهم احتياجك.','Software starts with understanding your needs.')}</strong><span class="muted">${t('استكشف أنواع الأعمال المختلفة في المعرض.','Explore the different types of work in our collection.')}</span></div>
    <section class="section" id="featured-work">${sectionHead(t('كل مشروع، حكاية مختلفة.','Every project, a different story.'),t('جميع الأعمال لها مكان في المعرض؛ عرض البداية مدخل للقائمة الكاملة.','Every project belongs in the collection. This introduction leads to all work.'),link(t('جميع الأعمال','View all work'),'work'))}<div class="grid">${projects.slice(0,3).map(card).join('')}</div></section>
    <section class="section rule">${sectionHead(t('نطوّر حول احتياجك.','Built around your needs.'),t('خدمتنا الأساسية: تطوير تطبيقات برمجية حسب طلب العميل.','Our core service: custom software development.'))}<div class="grid">${[[t('نبدأ باحتياجك','Understand your needs'),t('نحدد معك ما يحتاجه التطبيق وما يجب أن يحققه.','Define what your application needs to do.')],[t('نرتّب التجربة','Shape the experience'),t('نخطط للشاشات والمسارات قبل تنفيذها.','Plan screens and journeys before building them.')],[t('نعرض عملنا','Show our work'),t('تعرّف على أمثلة متنوعة من معرض المشاريع.','Explore a range of examples in the project collection.')]].map((a,i)=>`<div class="feature"><div class="feature-number">0${i+1}</div><h3>${a[0]}</h3><p class="muted">${a[1]}</p></div>`).join('')}</div></section>
    <section class="section">${cta()}</section></div></main>${footer()}`;
}
function work() { const list=projects.filter(p=>(filter==='all'||p.group===filter)&&(!search||name(p).toLowerCase().includes(search.toLowerCase()))); return `<main id="main" tabindex="-1" class="wrap section">${pageHead(t('معرض المشاريع','PROJECT COLLECTION'),t('أعمالنا، بتفاصيلها.','Our work, in detail.'),t('أنواع مختلفة من التطبيقات في قالب واضح ومتناسق.','Different types of software, presented with clarity.'))}<div class="spread"><label class="search">${t('ابحث عن مشروع','Search projects')}<input id="project-search" value="${esc(search)}" placeholder="${t('اسم المشروع...','Project name...')}" type="search"></label><span class="badge">${list.length} ${t('عنوانًا في المعاينة','reference titles')}</span></div><div class="filters" aria-label="${t('تصنيف الأعمال','Project categories')}">${['all','systems','sites','store','games'].map(g=>`<button class="chip" data-filter="${g}" aria-pressed="${filter===g}">${groupName(g)}</button>`).join('')}</div>${list.length?`<div class="grid">${list.map(card).join('')}</div>`:`<div class="panel empty"><h2>${t('مفيش نتائج للبحث ده','No matching projects')}</h2><p class="muted">${t('جرّب اسمًا مختلفًا أو اعرض كل الأعمال.','Try another name, or view the entire collection.')}</p>${btn(t('عرض الكل','Show all'),'reset-filter',true)}</div>`}</main>${footer()}`; }
function detail(p=projects.find(p=>p.id===current)||projects[0],preview=false) { return `${preview?'':`<main id="main" tabindex="-1" class="wrap section">`}${preview?'':`<a class="btn ghost" href="#work">${t('الرجوع للأعمال','Back to work')}</a>`}${pageHead(groupName(p.group),esc(name(p)),t('مرجع تصميم صفحة مشروع؛ المحتوى التفصيلي لم يقدم بعد.','Project-page design reference; final details have not been supplied.'))}<div class="detail-layout"><div><button class="detail-visual" data-action="lightbox" data-id="${p.id}" aria-label="${t('تكبير لقطة المشروع','Enlarge the project screenshot')}">${thumb(p)}</button><div class="detail-copy">${[[t('الاحتياج','The need'),t('يضيف الفريق هنا الاحتياج الفعلي الذي عالجه المشروع.','The team will describe the actual need addressed by this project.')],[t('الحل والوظائف','The solution & features'),t('مساحة لوصف الحل والوظائف الموثقة، بالعربية والإنجليزية.','Space for the solution and verified features in both languages.')],[t('مساهمة الفريق','Our contribution'),t('يوضح الفريق هنا نطاق المساهمة وحالة استخدام المشروع.','The team will explain its contribution and the project’s usage status.')]].map(a=>`<section><h2>${a[0]}</h2><p class="muted">${a[1]}</p></section>`).join('')}<div class="video"><div class="stack-sm" style="justify-items:center">${btn(t('معاينة موضع الفيديو','Video preview position'),'video',false,'play')}<span class="small muted">${t('غلاف قبل التشغيل — وسيط اختياري','Poster before playback — optional media')}</span></div></div></div></div><aside class="stack"><div class="panel stack-sm"><div class="eyebrow">${t('تفاصيل المشروع','PROJECT DETAILS')}</div><span class="muted">${t('النوع','Type')}</span><strong>${groupName(p.group)}</strong><div class="rule"></div><p class="small muted">${t('التصنيف مبدئي؛ التاريخ والتقنيات لا تعرض حتى يؤكدها الفريق.','The category is provisional. Dates and technologies appear after confirmation.')}</p></div><div class="panel stack-sm"><h3>${t('عندك احتياج مشابه؟','Have a similar need?')}</h3><p class="muted">${t('ابدأ طلبك بسياق هذا المشروع.','Start a request with this project as a reference.')}</p><button class="btn primary" data-action="similar" data-id="${p.id}">${t('اطلب حلًا مشابهًا','Request a similar solution')}${icon('arrow','arrow')}</button></div></aside></div>${preview?'':'</main>'+footer()}`; }
function field(id,label,type='text',hint='',value='') { const direction=id.endsWith('-ar')?' dir="rtl" lang="ar"':id.endsWith('-en')||['email','url','tel','password'].includes(type)?' dir="ltr"':''; return `<div class="field"><label for="${id}">${label}</label>${type==='textarea'?`<textarea id="${id}" name="${id}"${direction}>${esc(value)}</textarea>`:`<input id="${id}" name="${id}" type="${type}"${direction} value="${esc(value)}" ${type==='email'?'autocomplete="email"':type==='password'?'autocomplete="current-password"':''}>`}${hint?`<p>${hint}</p>`:''}</div>`; }
function contact() { const p=projects.find(p=>p.id===context); return `<main id="main" tabindex="-1" class="wrap">${pageHead(t('لنبدأ الحديث','LET’S TALK'),t('احكيلنا عن فكرتك.','Tell us about your idea.'),'')}<div class="contact-layout"><div class="stack"><p class="muted">${t('صف احتياجك والنتيجة التي تريد الوصول إليها. تفاصيل التواصل يضيفها الفريق لاحقًا.','Describe your need and the outcome you have in mind. The team will add contact channels later.')}</p>${p?`<div class="panel stack-sm"><span class="small muted">${t('مشروعك المرجعي','Your project reference')}</span><strong>${esc(name(p))}</strong><span class="latin small">${p.id}</span></div>`:''}<div class="note">${t('لا توجد أرقام أو عناوين افتراضية. القنوات تظهر بعد إدخالها من الأدمن.','No placeholder phone numbers or addresses. Channels appear after entry in the admin panel.')}</div></div><form class="panel stack" id="contact-form">${field('client-name',t('اسمك','Your name'))}${field('client-email',t('بريدك الإلكتروني','Your email'),'email')}${field('client-request',t('ماذا تحتاج؟','What do you need?'),'textarea')}<button class="btn primary" type="submit">${t('راجع شكل الطلب','Review the request')}</button><p class="small muted">${t('نموذج تصميم فقط؛ لا يتم إرسال طلبات في المرحلة 2.','Design prototype only. No requests are sent in Phase 02.')}</p></form></div></main>${footer()}`; }
function services() { return `<main id="main" tabindex="-1" class="wrap section">${pageHead(t('خدمات YOGEN','YOGEN SERVICES'),t('تطبيقات حسب احتياجك.','Software for your needs.'),t('الخدمة المؤكدة: إنشاء تطبيقات برمجية حسب طلب العميل.','Our confirmed service: custom software applications.'))}<div class="panel spread"><div class="stack-sm"><h2>${t('تطوير البرمجيات حسب الطلب','Custom software development')}</h2><p class="muted">${t('نرتب تفاصيل الحل وفق احتياج المشروع. أنواع المنصات والخدمات الإضافية تضبط مع الفريق قبل نشرها.','The solution is defined around your project. Specific platforms and additional services are confirmed with the team before publication.')}</p></div>${link(t('استكشف أمثلة الأعمال','Explore work examples'),'work')}</div><section class="section">${cta()}</section></main>${footer()}`; }
function about() { return `<main id="main" tabindex="-1" class="wrap section">${pageHead(t('عن الشركة','ABOUT YOGEN'),t('أفكار لمستقبل أكثر إشراقًا.','Ideas for a brighter tomorrow.'),t('YOGEN شركة برمجة تطوّر تطبيقات حسب طلب العميل.','YOGEN develops custom software applications.'))}<div class="two"><div class="panel stack"><h2>${t('نعرف نفسنا من أعمالنا.','Our work tells our story.')}</h2><p class="muted">${t('استكشف المشاريع وتعرف على أنواع الحلول التي شارك فيها الفريق.','Explore the projects and the different kinds of solutions the team has worked on.')}</p>${link(t('معرض الأعمال','Project collection'),'work')}</div><div class="panel stack"><h2>${t('مساحة الفريق','Team section')}</h2><p class="muted">${t('في هذه المعاينة فقط: القسم العام يخفى حتى يدخل الفريق ملفات كاملة. الأسماء والصور لم تقدم، ويمكن إضافتها من الأدمن لاحقًا.','Prototype annotation: the public section stays hidden until complete team profiles are added. Names and photos have not been supplied and can be entered later.')}</p>${link(t('معاينة إدارة الفريق','Preview team management'),'admin/team')}</div></div></main>${footer()}`; }
const adminNav = () => [['admin',t('نظرة عامة','Overview'),'grid'],['admin/projects',t('المشاريع','Projects'),'grid'],['admin/media',t('مكتبة الوسائط','Media library'),'image'],['admin/categories',t('التصنيفات','Categories'),'grid'],['admin/team',t('بيانات الفريق','Team profiles'),'user'],['admin/company',t('الشركة والتواصل','Company & contact'),'mail'],['admin/accounts',t('الحسابات والصلاحيات','Accounts & roles'),'user'],['admin/storage',t('التخزين والوسائط','Storage & media'),'settings']];
function shell(content) { return `<div class="admin-shell"><aside class="sidebar"><strong class="side-label">${t('مساحة الفريق','Team workspace')}</strong><nav class="side-links" aria-label="${t('تنقل الأدمن','Admin navigation')}">${adminNav().map(([r,n,i])=>`<a href="#${r}" class="${route()===r?'active':''}">${icon(i)}${n}</a>`).join('')}</nav><small>${t('جميع الأعضاء مخولون بالنشر','All team members can publish')}</small></aside><main id="main" tabindex="-1" class="admin-content">${content}</main></div>`; }
function adminTitle(title,sub='') { return `<div class="admin-title"><div class="eyebrow">${t('لوحة إدارة YOGEN','YOGEN ADMIN')}</div><h1>${title}</h1><p class="muted">${sub}</p></div>`; }
function projectList(limit=15) { return `<div class="project-list"><div class="table-row head"><span>${t('المشروع','Project')}</span><span>${t('الحالة','Status')}</span><span>${t('الإجراءات','Actions')}</span></div>${projects.slice(0,limit).map(p=>`<div class="table-row"><div class="mini-project">${thumb(p,false)}<div><strong>${esc(name(p))}</strong><span class="small muted">${groupName(p.group)}</span></div></div><span class="badge ${mockPublished&&p.id===current?'success':'warning'}">${mockPublished&&p.id===current?t('منشور في النموذج','Prototype published'):t('مسودة مرجعية','Reference draft')}</span><div class="row"><a class="btn" href="#admin/editor/${p.id}">${t('تعديل','Edit')}</a><a class="icon-btn" href="#project/${p.id}" aria-label="${t('معاينة المشروع','Preview project')}">${icon('eye')}</a></div></div>`).join('')}</div>`; }
function overview() { return shell(`${adminTitle(t('خلّي أعمالك تتكلم.','Let your work speak.'),t('جهّز المشاريع، راجع المحتوى، وانشر بعد اكتماله.','Prepare projects, review content, and publish when ready.'))}<div class="spread"><p class="muted">${t('الأعداد في نموذج التصميم؛ لا بيانات سحابية متصلة.','Counts are from the design model, with no cloud connection.')}</p>${link(t('أضف مشروعًا','Add a project'),'admin/editor/new',true)}</div><div class="stats">${[[mockPublished?1:0,t('منشور في النموذج','Prototype published')],[mockPublished?14:15,t('مسودات مرجعية','Reference drafts')],[0,t('مؤرشف','Archived')]].map(([n,l])=>`<div class="stat"><span class="muted">${l}</span><strong>${n}</strong></div>`).join('')}</div>${sectionHead(t('مشاريع بحاجة لاستكمال','Projects to complete'),'',link(t('كل المشاريع','All projects'),'admin/projects'))}${projectList(4)}`); }
function adminProjects() { return shell(`${adminTitle(t('مشاريع YOGEN','YOGEN projects'),t('إضافة وتعديل ومعاينة من نفس المكان.','Add, edit, and preview in one place.'))}<div class="spread" style="margin-bottom:24px"><span class="badge">15 ${t('عنوانًا مرجعيًا','reference titles')}</span>${link(t('أضف مشروعًا','Add a project'),'admin/editor/new',true)}</div>${projectList()}`); }
function collectForm() { const form=document.querySelector('#editor-form'); if(form) new FormData(form).forEach((v,k)=>formValues[k]=v); }
function editor() { const p=projects.find(p=>p.id===current)||projects[0]; const fieldsContent=`<div class="panel stack"><div class="spread"><h2>${t('المحتوى الأساسي','Core content')}</h2><span class="badge warning">${t('اللغتان قبل النشر','Both languages before publishing')}</span></div><div class="two">${field('name-ar',t('الاسم بالعربية','Arabic title'),'text','',formValues['name-ar']??p.name)}${field('name-en',t('الاسم بالإنجليزية','English title'),'text','',formValues['name-en']??p.en)}${field('summary-ar',t('الوصف المختصر بالعربية','Arabic short description'),'textarea','',formValues['summary-ar']??'')}${field('summary-en',t('الوصف المختصر بالإنجليزية','English short description'),'textarea','',formValues['summary-en']??'')}</div>${field('details',t('الاحتياج والحل والوظائف والمساهمة','Need, solution, features & contribution'),'textarea',t('حقول منظمة لكل لغة عند التنفيذ؛ هذه مساحة معاينة لتجميع المحتوى.','Structured fields per language in implementation; this is a layout preview.'),formValues.details??'')}<div class="two">${field('category',t('التصنيف','Category'),'text','',groupName(p.group))}${field('usage',t('حالة الاستخدام','Usage status'),'text',t('فعلي / تجريبي / شخصي — يحددها الفريق','Real use / demo / personal — confirmed by the team'),'')}</div></div>`;
const fieldsMedia=`<div class="panel stack"><h2>${t('الغلاف ومعرض الصور','Cover & image gallery')}</h2><div class="upload-box"><div class="stack-sm" style="justify-items:center">${icon('upload')}<strong>${t('اختر صور المشروع','Choose project images')}</strong><p class="muted">${t('رفع من داخل اللوحة؛ الأنواع والحدود تتحدد في المرحلة التقنية.','Upload from the panel; types and limits are defined in technical validation.')}</p>${btn(t('محاكاة اختيار صورة','Simulate selecting an image'),'select-media')}</div></div><div class="two"><div>${thumb(p)}<div class="row" style="margin-top:12px"><span class="badge">${t('غلاف مرجعي','Reference cover')}</span>${btn(t('ترتيب الصور','Reorder images'),'reorder')}</div></div><div class="stack">${field('alt-ar',t('الوصف البديل بالعربية','Arabic alternative text'))}${field('alt-en',t('الوصف البديل بالإنجليزية','English alternative text'))}</div></div><div class="rule"></div><h3>${t('فيديو ومرفقات اختيارية','Optional video & attachments')}</h3><p class="muted">${t('الغلاف يسبق تشغيل الفيديو؛ لا تحميل لكل الفيديوهات أثناء فتح المعرض.','A poster appears before video playback. Videos are not all loaded on entry.')}</p></div>`;
const fieldsPublish=`<div class="panel stack"><h2>${t('النشر والظهور','Publication & visibility')}</h2><div class="message warning">${icon('alert')}<div>${t('المحتوى الحالي مسودة؛ الرابط والتاريخ والتقنيات اختيارية.','The current content is a draft. Demo links, dates, and technologies are optional.')}</div></div>${field('slug',t('عنوان صفحة المشروع','Page slug'),'text','',current.toLowerCase())}${field('demo-link',t('رابط عرض اختياري','Optional demo link'),'url')}${field('contribution',t('نطاق مساهمة الفريق','Team contribution'),'textarea')}<div class="row">${btn(t('إلغاء النشر في النموذج','Simulate unpublish'),'unpublish')}${btn(t('محاكاة أرشفة','Simulate archive'),'archive')}${btn(t('استعادة كمسودة','Restore as draft'),'restore')}</div></div>`;
return shell(`${adminTitle(t('تحرير المشروع','Project editor'),t('حفظ المسودة مستقل عن نشر التعديلات.','Saving a draft is separate from publishing changes.'))}<div class="message ${mockPublished?'success':'warning'}">${icon(mockPublished?'check':'alert')}<span>${mockPublished?t('نسخة منشورة في النموذج؛ التعديل يبقى مسودة حتى نشره.','Prototype has a published version. Edits remain a draft until published.'):t('مسودة خاصة في نموذج التصميم؛ لا نشر حقيقي.','A private draft in the design model. No real publication.')}</span></div><div class="tabs" role="tablist" aria-label="${t('أجزاء محرر المشروع','Project editor sections')}">${[['content',t('المحتوى','Content')],['media',t('الصور والملفات','Media')],['publish',t('النشر والروابط','Publishing')]].map(([k,n])=>`<button role="tab" data-tab="${k}" aria-selected="${tab===k}">${n}</button>`).join('')}</div><div class="editor-layout"><form id="editor-form" class="editor-form">${tab==='content'?fieldsContent:tab==='media'?fieldsMedia:fieldsPublish}</form><aside class="panel editor-summary stack-sm"><h3>${t('جاهزية النشر','Publish readiness')}</h3><span class="badge ${sampleReady?'success':'warning'}">${sampleReady?t('عينة تصميم مكتملة','Complete design sample'):t('محتوى غير مكتمل','Incomplete content')}</span><ul class="checklist"><li>${t('الاسم والمحتوى باللغتين','Title & content in both languages')}</li><li>${t('التصنيف والحالة والمساهمة','Category, usage & contribution')}</li><li>${t('الغلاف جاهز ووصفه مكتمل','Cover ready, alt text complete')}</li></ul>${btn(t('استخدم عينة تصميم مكتملة','Use complete design sample'),'complete-sample')}<p class="small muted">${t('العينة لا تمثل حقائق المشروع ولا تحفظ خارج المعاينة.','The sample is not project facts and is not saved outside this preview.')}</p></aside></div><div id="publish-errors"></div><div class="action-bar">${btn(t('حفظ مسودة','Save draft'),'save-draft')}${btn(t('معاينة','Preview'),'preview',false,'eye')}${btn(mockPublished?t('نشر التعديلات','Publish changes'):t('نشر','Publish'),'publish',true)}</div><p class="small muted" id="save-status">${saved?t('محاكاة: تم حفظ المسودة في ذاكرة المعاينة فقط.','Simulation: draft saved only in prototype memory.'):t('لا تغييرات محفوظة على أي خدمة.','No changes have been saved to any service.')}</p>`); }
function login() { return `<main id="main" tabindex="-1"><form class="panel stack login" id="login-form"><div class="eyebrow">${t('مساحة YOGEN الخاصة','YOGEN TEAM WORKSPACE')}</div><h1 style="font-size:36px">${t('أهلًا بفريقك.','Welcome, team.')}</h1><p class="muted">${t('نموذج دخول توضيحي؛ مزود الدخول يتحدد عند الربط.','Illustrative sign-in. The provider is chosen during setup.')}</p>${field('login-email',t('البريد الإلكتروني','Email'),'email')}${field('login-password',t('كلمة المرور','Password'),'password')}<button class="btn primary" type="submit">${t('دخول تجريبي للمعاينة','Enter the design preview')}</button><button type="button" class="btn ghost" data-action="recover">${t('استعادة الوصول','Recover access')}</button></form></main>`; }
function media() { return shell(`${adminTitle(t('مكتبة الوسائط','Media library'),t('صور وملفات مرتبطة بالمشاريع؛ التخزين الفعلي في Drive لاحقًا.','Images and files linked to projects. Real Drive storage comes later.'))}<div class="spread" style="margin-bottom:24px"><span class="badge">${t('أصول مرجعية فقط','Reference assets only')}</span>${btn(t('رفع ملف — محاكاة','Upload file — simulation'),'select-media',true,'upload')}</div><div class="grid">${projects.slice(0,3).map(p=>`<div class="panel stack-sm">${thumb(p)}<strong>${esc(name(p))}</strong><div class="row">${btn(t('معاينة','Preview'),'media-preview',false,'eye')}<span class="badge">${t('مرجع صورة','Image reference')}</span></div></div>`).join('')}</div>`); }
function team() { return shell(`${adminTitle(t('بيانات الفريق','Team profiles'),t('الملفات العامة مستقلة عن حسابات الدخول.','Public profiles are separate from sign-in accounts.'))}<div class="panel empty"><span class="empty-icon">${icon('user')}</span><h2>${t('أضف بياناتكم وقت ما تكونوا جاهزين.','Add your details when you’re ready.')}</h2><p class="muted">${t('الفريق حاليًا ثلاثة أعضاء. الأسماء والصور لم تدخل؛ القسم العام مخفي حتى تكتمل الملفات.','The team currently has three members. Names and photos are not entered; the public section stays hidden until profiles are complete.')}</p>${btn(t('إضافة ملف عضو','Add a team profile'),'team-form',true,'plus')}</div><div id="team-form-area" class="section" hidden><form class="panel stack" id="profile-form"><div class="two">${field('member-ar',t('الاسم بالعربية','Arabic name'))}${field('member-en',t('الاسم بالإنجليزية','English name'))}${field('role-ar',t('الدور بالعربية','Arabic role'))}${field('role-en',t('الدور بالإنجليزية','English role'))}</div>${field('bio',t('نبذة اختيارية','Optional biography'),'textarea')}<div class="upload-box">${btn(t('اختيار صورة — محاكاة','Select photo — simulation'),'select-media')}</div><div class="row"><button class="btn primary" type="submit">${t('حفظ مخفي — محاكاة','Save hidden — simulation')}</button>${btn(t('معاينة الظهور','Preview visibility'),'profile-preview')}</div></form></div>`); }
function company() { return shell(`${adminTitle(t('الشركة والتواصل','Company & contact'),t('تدخل البيانات لاحقًا من هنا، وتتحدث الروابط في الموقع.','Enter details here later. Public links update from these settings.'))}<form class="panel stack" id="company-form"><div class="message">${icon('mail')}<span>${t('القنوات الفارغة لا تظهر للزوار.','Empty channels do not appear to visitors.')}</span></div><div class="two">${field('company-ar',t('نبذة عربية','Arabic introduction'),'textarea','',t('تطوير تطبيقات برمجية حسب طلب العميل',''))}${field('company-en',t('نبذة إنجليزية','English introduction'),'textarea','','Custom software development')}${field('whatsapp',t('رقم واتساب الشركة','Company WhatsApp number'),'tel')}${field('business-email',t('البريد التجاري','Business email'),'email')}</div>${field('social-link',t('رابط رسمي اختياري','Optional official link'),'url')}<div class="action-bar"><button class="btn primary" type="submit">${t('محاكاة حفظ الإعدادات','Simulate saving settings')}</button>${btn(t('معاينة القنوات الظاهرة','Preview visible channels'),'contact-preview')}</div><p class="small muted">${t('لا أرقام أو بريد جاهز، ولا اتصال خارجي في هذه المعاينة.','No phone or email is prefilled. This prototype makes no external connection.')}</p></form>`); }
function categories() { return shell(`${adminTitle(t('التصنيفات والوسوم','Categories & tags'),t('التصنيفات مبدئية وتحتاج مراجعة محتوى الفريق.','Categories are provisional until reviewed with the team.'))}<div class="panel stack">${['systems','sites','store','games'].map(g=>`<div class="spread rule" style="padding-top:16px"><strong>${groupName(g)}</strong><span class="badge">${projects.filter(p=>p.group===g).length} ${t('عناوين','titles')}</span>${btn(t('تعديل اللغتين','Edit both languages'),'category-edit')}</div>`).join('')}${btn(t('إضافة تصنيف','Add category'),'category-edit',true,'plus')}</div>`); }
function accounts() { return shell(`${adminTitle(t('الحسابات والصلاحيات','Accounts & roles'),t('جميع أعضاء الفريق يستطيعون نشر المشاريع.','All team members can publish projects.'))}<div class="panel stack"><h2>${t('الوصول مستقل عن الملف العام.','Access is separate from public profiles.')}</h2><p class="muted">${t('بيانات الدخول وهوية المدير الأول تتحدد في مرحلة الحسابات. لا تظهر أسماء وهمية هنا.','Sign-in details and the first administrator are chosen in the accounts phase. No fictional names are listed.')}</p><div class="two"><div class="note"><strong>${t('عضو فريق مخول','Authorized team member')}</strong><p>${t('مشاريع، وسائط، مسودات، معاينة، نشر.','Projects, media, drafts, preview, publish.')}</p></div><div class="note"><strong>${t('مدير','Administrator')}</strong><p>${t('ما سبق، مع إدارة الحسابات وإعدادات الربط.','All of the above, plus account and storage settings.')}</p></div></div>${btn(t('معاينة دعوة عضو','Preview member invitation'),'invite',true)}</div>`); }
function storage() { return shell(`${adminTitle(t('التخزين والوسائط','Storage & media'),t('إعداد الربط للمدير؛ لا تكشف القيم في الصفحات العامة.','Administrator connection settings. Values stay out of public pages.'))}<form class="panel stack" id="storage-form"><span class="badge warning">${t('غير مربوط في نموذج التصميم','Not connected in the design model')}</span>${field('drive-account',t('بريد مساحة الشركة','Company storage email'),'email')}${field('script-url',t('رابط خدمة الرفع','Upload service URL'),'url')}${field('root-folder',t('المجلد الرئيسي','Root folder'),'text','', 'YOGEN Portfolio')}<div class="row">${btn(t('اختبار الاتصال — معاينة','Connection test — preview'),'connection',true)}${btn(t('حفظ الإعدادات — معاينة','Save settings — preview'),'storage-save')}</div><p class="small muted">${t('النموذج لا يجري اتصالًا بـDrive أو Firebase؛ الربط والتحقق في المرحلة 3.','No connection to Drive or Firebase is made. Technical validation belongs to Phase 03.')}</p></form>`); }
function states() { return `<main id="main" tabindex="-1" class="wrap section">${pageHead(t('مرجع الحالات','STATE REFERENCE'),t('تجربة واضحة، حتى وقت الخطأ.','Clarity, even when things go wrong.'),t('حالات التصميم الأساسية للموقع والأدمن.','Key interface states for the website and admin.'))}<div class="state-grid"><div class="panel"><h3>${t('تحميل المحتوى','Loading content')}</h3><div class="skeleton image"></div><div class="skeleton"></div><p class="muted">${t('مساحة الصورة والعنوان محجوزة.','Image and title space is reserved.')}</p></div><div class="panel"><h3>${t('الصورة غير متاحة','Image unavailable')}</h3><div class="upload-box">${icon('image')}<p>${t('تعذر تحميل الصورة؛ المحتوى ما زال مقروءًا.','The image could not load. Content remains readable.')}</p></div>${btn(t('إعادة المحاولة','Retry'),'retry')}</div><div class="panel"><h3>${t('رفع جارٍ','Upload in progress')}</h3><div class="progress" role="progressbar" aria-label="${t('تقدم توضيحي للرفع','Illustrative upload progress')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="42"><span></span></div><p class="muted">${t('42% توضيحية فقط. عند التنفيذ لا نسبة دون قياس فعلي.','42% is illustrative. Real percentages require measurable progress.')}</p><div class="message warning">${icon('upload')}${t('الرفع لم يكتمل؛ النشر ينتظر الملف.','Upload is incomplete. Publishing awaits the file.')}</div></div><div class="panel"><h3>${t('الإنجليزية ناقصة','English content missing')}</h3><div class="field error"><label for="missing-en">${t('الوصف الإنجليزي','English description')}</label><input id="missing-en" aria-invalid="true" aria-describedby="missing-error"><p id="missing-error">${t('أكمل الوصف الإنجليزي قبل النشر. المسودة يمكن حفظها.','Complete the English description before publication. Saving a draft is allowed.')}</p></div></div><div class="panel"><h3>${t('تعديل مشروع منشور','Editing a published project')}</h3><div class="message success">${icon('check')}${t('النسخة الحالية تظهر للزوار.','The current published version is visible.')}</div><div class="note">${t('التعديلات مسودة خاصة إلى أن تنشرها.','Changes remain a private draft until you publish them.')}</div>${link(t('معاينة المحرر','Preview editor'),'admin/editor/P001')}</div><div class="panel"><h3>${t('الأرشفة والاستعادة','Archive & restore')}</h3><p class="muted">${t('المؤرشف خارج المعرض؛ المحتوى والوسائط باقية. الاستعادة تعيد مسودة.','Archived work is outside the collection. Content and media remain. Restoration returns a draft.')}</p>${btn(t('محاكاة استعادة','Simulate restore'),'restore')}</div><div class="panel"><h3>${t('فشل الحفظ','Save failed')}</h3><div class="message error">${icon('alert')}${t('التغييرات لم تحفظ. حافظنا على المدخلات؛ أعد المحاولة.','Changes were not saved. Inputs are retained; try again.')}</div>${btn(t('إعادة الحفظ','Retry save'),'save-draft')}</div><div class="panel"><h3>${t('الحركة العادية والمخففة','Standard & reduced motion')}</h3><p class="muted">${t('مجسّم بإضاءة وحركة يمكن إيقافها، وظهور أقسام وانتقالات. النسخة المخففة ثابتة والتمرير طبيعي.','An illuminated, pausable 3D scene, section entrances and transitions. Reduced motion stays static; scrolling remains natural.')}</p>${btn(reduced?t('عرض الحركة العادية','Show standard motion'):t('عرض الحركة المخففة','Show reduced motion'),'motion')}</div></div></main>${footer()}`; }
function render(focus=false,change='') {
  window.YogenMotion?.destroy();
  document.documentElement.lang=lang; document.documentElement.dir=lang==='ar'?'rtl':'ltr'; document.documentElement.dataset.theme=theme; document.documentElement.dataset.reduced=String(reduced);
  const r=route(), admin=r.startsWith('admin');
  document.querySelector('#review-bar').innerHTML=`<span>${t('معاينة تصميم المرحلة 2 · تفاعلات توضيحية فقط','Phase 02 design preview · illustrative interactions only')}</span><div class="row review-links"><a href="#states">${t('حالات الواجهة','UI states')}</a><a href="#login">${t('معاينة الأدمن','Admin preview')}</a></div>`;
  document.querySelector('#header').innerHTML=`<div class="wrap nav">${brand()}<nav class="nav-links" aria-label="${t('التنقل الرئيسي','Primary navigation')}">${[['home',t('الرئيسية','Home')],['work',t('أعمالنا','Work')],['services',t('خدماتنا','Services')],['about',t('عن YOGEN','About')]].map(([to,n])=>`<a href="#${to}" class="${r===to?'active':''}">${n}</a>`).join('')}</nav><div class="controls"><button class="btn" data-action="lang" aria-label="${t('تغيير اللغة إلى الإنجليزية','Switch to Arabic')}">${lang==='ar'?'EN':'عربي'}</button><button class="icon-btn" data-action="theme" aria-label="${t('تغيير الوضع اللوني','Change color mode')}">${icon(theme==='dark'?'sun':'moon')}</button><button class="icon-btn menu-toggle" data-action="menu" aria-label="${t('فتح القائمة','Open navigation')}" aria-expanded="false">${icon('menu')}</button></div><a class="btn primary nav-start" href="#${admin?'admin/editor/new':'contact'}">${admin?t('أضف مشروعًا','Add project'):t('ابدأ مشروعك','Start a project')}</a></div>`;
  let html;
  if(r==='home')html=home(); else if(r==='work')html=work(); else if(r.startsWith('project/')){current=r.split('/')[1];html=detail();}
  else if(r==='contact')html=contact(); else if(r==='services')html=services(); else if(r==='about')html=about(); else if(r==='login')html=login();
  else if(r==='admin')html=overview(); else if(r==='admin/projects')html=adminProjects(); else if(r.startsWith('admin/editor')){current=r.split('/')[2]||'P001';html=editor();}
  else if(r==='admin/media')html=media(); else if(r==='admin/categories')html=categories(); else if(r==='admin/team')html=team(); else if(r==='admin/company')html=company(); else if(r==='admin/accounts')html=accounts(); else if(r==='admin/storage')html=storage(); else html=states();
  document.querySelector('#app').innerHTML=html;
  if(focus)document.querySelector('#main')?.focus({preventScroll:true});
  window.YogenMotion?.mount({change});
}
document.addEventListener('click',e=>{
  const projectLink=e.target.closest('[data-project]');
  if(projectLink)window.YogenMotion?.capture(projectLink.querySelector('.thumb'));
  const el=e.target.closest('[data-action],[data-filter],[data-tab]'); if(!el)return;
  const action=el.dataset.action;
  if(el.dataset.filter){filter=el.dataset.filter;render(false,'filter');document.querySelector(`[data-filter="${filter}"]`)?.focus({preventScroll:true});return;}
  if(el.dataset.tab){collectForm();tab=el.dataset.tab;render(false,'tab');document.querySelector(`[data-tab="${tab}"]`)?.focus({preventScroll:true});return;}
  if(action==='lang'){collectForm();lang=lang==='ar'?'en':'ar';render();document.querySelector('[data-action="lang"]')?.focus({preventScroll:true});}
  else if(action==='theme'){collectForm();theme=theme==='dark'?'light':'dark';render(false,'theme');document.querySelector('[data-action="theme"]')?.focus({preventScroll:true});}
  else if(action==='pause-scene'){window.YogenMotion?.pause();}
  else if(action==='scroll-work'){document.querySelector('#featured-work')?.scrollIntoView({behavior:window.YogenMotion?.reduced()?'instant':'smooth',block:'start'});}
  else if(action==='menu'){const n=document.querySelector('.nav-links');n.classList.toggle('open');el.setAttribute('aria-expanded',String(n.classList.contains('open')));if(n.classList.contains('open'))window.YogenMotion?.animate(n,[{opacity:.3,transform:'translateY(-8px)'},{opacity:1,transform:'none'}],{duration:260,easing:'ease-out'});}
  else if(action==='similar'){context=el.dataset.id;location.hash='contact';}
  else if(action==='reset-filter'){search='';filter='all';render();}
  else if(action==='save-draft'){collectForm();saved=true;const s=document.querySelector('#save-status');if(s)s.textContent=t('محاكاة: المسودة محفوظة في ذاكرة المعاينة فقط.','Simulation: the draft is saved only in prototype memory.');toast(t('تمت محاكاة الحفظ؛ لا بيانات سحابية تغيرت.','Draft-save simulated. No cloud data changed.'));}
  else if(action==='complete-sample'){sampleReady=true;collectForm();formValues['summary-ar']='نص تصميم توضيحي — يحتاج استبدالًا بمحتوى موثق.';formValues['summary-en']='Illustrative design text — replace with verified content.';render();}
  else if(action==='publish'){collectForm();if(!sampleReady){const area=document.querySelector('#publish-errors');area.innerHTML=`<div class="message error" role="alert" tabindex="-1">${icon('alert')}${t('البيانات غير مكتملة. أكمل المحتوى باللغتين والغلاف والمساهمة، أو استخدم عينة التصميم لاختبار المسار.','Content is incomplete. Add both languages, the cover and contribution, or use the design sample to test the flow.')}</div>`;area.firstElementChild.focus();}else{mockPublished=true;render();toast(t('تمت محاكاة النشر في النموذج فقط.','Publication simulated in the design model only.'));}}
  else if(action==='preview'){collectForm();const d=document.querySelector('#preview');d.innerHTML=`<div class="spread"><h2 id="preview-title">${t('معاينة التصميم','Design preview')}</h2>${btn(t('إغلاق','Close'),'close-preview')}</div><div class="dialog-content">${detail(projects.find(p=>p.id===current)||projects[0],true)}</div>`;d.showModal();window.YogenMotion?.dialog(d);}
  else if(action==='close-preview')window.YogenMotion.closeDialog(document.querySelector('#preview'));
  else if(action==='lightbox'){current=el.dataset.id;galleryIndex=0;openLightbox();}
  else if(action==='close-lightbox')window.YogenMotion.closeDialog(document.querySelector('#lightbox'));
  else if(action==='next-image'){galleryIndex=(galleryIndex+1)%2;openLightbox(false);}
  else if(action==='motion'){reduced=!reduced;render();}
  else if(action==='team-form'){document.querySelector('#team-form-area').hidden=false;document.querySelector('#member-ar').focus();}
  else if(['archive','unpublish','restore'].includes(action)){mockPublished=false;toast(t('محاكاة: المشروع خارج المعرض، والمحتوى والوسائط محفوظة للاستعادة كمسودة.','Simulation: the project is outside the collection; content and media remain for restoration as a draft.'));}
  else if(action==='select-media')toast(t('هذه معاينة اختيار ورفع؛ لا ملف يرفع فعليًا.','This previews file selection and upload. No file is uploaded.'));
  else if(action==='connection')toast(t('شكل اختبار الاتصال فقط؛ لم يحدث اتصال حقيقي.','Connection-test appearance only. No real connection was made.'));
  else toast(t('تفاعل توضيحي ضمن تصميم المرحلة 2.','Illustrative interaction in the Phase 02 design.'));
});
function openLightbox(open=true){const p=projects.find(p=>p.id===current)||projects[0],d=document.querySelector('#lightbox');d.innerHTML=`<div class="spread"><h2 id="lightbox-title">${esc(name(p))}</h2>${btn(t('إغلاق','Close'),'close-lightbox')}</div><div class="dialog-content">${thumb(p)}<div class="spread" style="margin-top:16px"><span class="muted">${t('معاينة معرض الصور','Image-gallery preview')} · ${galleryIndex+1}/2</span>${btn(t('الصورة التالية','Next image'),'next-image')}</div><p class="small muted">${t('نفس اللقطة المرجعية لتجربة أدوات المعرض؛ الصور المنفصلة لم تقدم.','The same reference screenshot is used to review gallery controls; separate images are not supplied.')}</p></div>`;if(open){d.showModal();window.YogenMotion?.dialog(d,document.querySelector('#app .detail-visual .thumb'));}else window.YogenMotion?.animate(d.querySelector('.dialog-content'),[{opacity:.5,transform:'translateX(12px)'},{opacity:1,transform:'none'}],{duration:260,easing:'ease-out'});}
document.addEventListener('input',e=>{if(e.target.id==='project-search'){const pos=e.target.selectionStart;search=e.target.value;render(false,'search');const n=document.querySelector('#project-search');n.focus();n.setSelectionRange(pos,pos);}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='login-form')location.hash='admin';else toast(t('تمت مراجعة الشكل في النموذج؛ لا حفظ أو إرسال خارجي.','Layout reviewed in the prototype. Nothing is saved or sent externally.'));});
window.addEventListener('hashchange',()=>{window.scrollTo({top:0,behavior:'instant'});render(true);});
window.addEventListener('yogenmotionchange',()=>render());
render();
